import os

targets = []
for root, dirs, files in os.walk('.'):
    # Skip the skill's own scripts to keep output small
    if '.codex' in root:
        continue
    for f in files:
        if f.endswith('.docx'):
            targets.append(os.path.join(root, f))

for t in sorted(targets):
    print(t)

"""Task helper: inspect quarterly_report.docx body structure (paragraphs/tables)."""
import xml.etree.ElementTree as ET

W = "{http://schemas.openxmlformats.org/wordprocessingml/2006/main}"
tree = ET.parse("quarterly_report_unpacked/word/document.xml")
body = tree.getroot().find(W + "body")


def para_text(p):
    parts = []
    for node in p.iter():
        if node.tag in (W + "t", W + "delText"):
            parts.append(node.text or "")
    return "".join(parts)


for i, child in enumerate(body):
    if child.tag == W + "p":
        txt = para_text(child).strip()
        print(i, "P:", txt[:140])
    elif child.tag == W + "tbl":
        print(i, "TABLE")
    elif child.tag == W + "sectPr":
        print(i, "SECTPR")
    else:
        print(i, child.tag)

